def migrate_member_tiers(apps, schema_editor):
    """將現有會員的 tier_legacy 值轉換到 tier_new"""
    Member = apps.get_model('member', 'Member')
    Tier = apps.get_model('member', 'Tier')
    
    legacy_to_new = {
        'A': 'free',
        'B': 'basic',
    }
    
    for member in Member.objects.all():
        old_tier = member.tier_legacy or 'A'
        new_tier_code = legacy_to_new.get(old_tier, 'free')
        try:
            member.tier_new = Tier.objects.get(code=new_tier_code)
            member.save(update_fields=['tier_new'])
        except Tier.DoesNotExist:
            pass


def reverse_tiers(apps, schema_editor):
    """反向遷移（回滾用）"""
